#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cctype>
using namespace std;

using ll = long long;

const int MAX_SIZE = 262144;
const int MAX_POWER = 18;

int L_val, n_val, k_val, Mo_val, len_val;
vector<int> bit_vec;
vector<int> cnt_vec(MAX_SIZE + 1);
vector<vector<int>> g_mat(20, vector<int>(MAX_SIZE));
vector<vector<int>> f_mat(20, vector<int>(MAX_SIZE));
vector<int> h_vec(20), p_vec(20);
vector<int> fac_vec(MAX_SIZE), inv_vec(MAX_SIZE);

int mod_exp(int base, int exp) {
    int result = 1;
    base %= Mo_val;
    while (exp > 0) {
        if (exp & 1) result = (ll)result * base % Mo_val;
        base = (ll)base * base % Mo_val;
        exp >>= 1;
    }
    return result;
}

void add_mod(int& x, int y) {
    x = (x + y) % Mo_val;
    if (x < 0) x += Mo_val;
}

void sub_mod(int& x, int y) {
    x = (x - y + Mo_val) % Mo_val;
}

void FWT_transform(vector<int>& arr, int sz) {
    for (int step = 1; step < sz; step <<= 1) {
        for (int start = 0; start < sz; start += step << 1) {
            for (int idx = 0; idx < step; idx++) {
                add_mod(arr[start + idx + step], arr[start + idx]);
            }
        }
    }
}

void IFWT_transform(vector<int>& arr, int sz) {
    for (int step = 1; step < sz; step <<= 1) {
        for (int start = 0; start < sz; start += step << 1) {
            for (int idx = 0; idx < step; idx++) {
                sub_mod(arr[start + idx + step], arr[start + idx]);
            }
        }
    }
}

void log_series(vector<int>& input, vector<int>& output, int max_n) {
    output[0] = 0;
    for (int i = 1; i <= max_n; i++) {
        output[i] = (ll)input[i] * i % Mo_val;
        for (int j = 1; j < i; j++) {
            sub_mod(output[i], (ll)output[j] * input[i - j] % Mo_val * j % Mo_val);
        }
        output[i] = (ll)output[i] * mod_exp(i, Mo_val - 2) % Mo_val;
    }
}

void exp_series(vector<int>& input, vector<int>& output, int max_n) {
    output[0] = 1;
    for (int i = 1; i <= max_n; i++) {
        output[i] = 0;
        for (int j = 1; j <= i; j++) {
            add_mod(output[i], (ll)input[j] * output[i - j] % Mo_val * j % Mo_val);
        }
        output[i] = (ll)output[i] * mod_exp(i, Mo_val - 2) % Mo_val;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> L_val >> k_val >> Mo_val;
    int total = mod_exp(k_val, L_val);

    if (L_val & 1) {
        cout << total << '\n';
        return 0;
    }

    fac_vec[0] = 1;
    for (int i = 1; i <= L_val; i++) {
        fac_vec[i] = (ll)fac_vec[i - 1] * i % Mo_val;
    }

    inv_vec[L_val] = mod_exp(fac_vec[L_val], Mo_val - 2);
    for (int i = L_val - 1; i >= 0; i--) {
        inv_vec[i] = (ll)inv_vec[i + 1] * (i + 1) % Mo_val;
    }

    for (int s = 1; s <= L_val; s++) {
        cnt_vec[s] = cnt_vec[s & (s - 1)] + 1;
    }

    n_val = 0;
    for (int i = 0; i <= MAX_POWER; i++) {
        if ((L_val >> i) & 1) {
            bit_vec.push_back(1 << i);
            n_val++;
        }
    }

    len_val = 1 << n_val;

    for (int i = 0; i < len_val; i++) {
        int sum_val = 0;
        for (int j = 0; j < n_val; j++) {
            if ((i >> j) & 1) {
                sum_val += bit_vec[j];
            }
        }
        g_mat[cnt_vec[i]][i] = inv_vec[sum_val];
    }

    for (int i = 0; i <= n_val; i++) {
        FWT_transform(g_mat[i], len_val);
    }

    for (int s = 0; s < len_val; s++) {
        for (int i = 0; i <= n_val; i++) {
            h_vec[i] = g_mat[i][s];
        }
        log_series(h_vec, p_vec, n_val);
        for (int i = 0; i <= n_val; i++) {
            p_vec[i] = (ll)p_vec[i] * k_val % Mo_val;
        }
        exp_series(p_vec, h_vec, n_val);
        for (int i = 0; i <= n_val; i++) {
            f_mat[i][s] = h_vec[i];
        }
    }

    IFWT_transform(f_mat[n_val], len_val);
    int result = (ll)f_mat[n_val][len_val - 1] * fac_vec[L_val] % Mo_val;
    result = (total - result + Mo_val) % Mo_val;
    cout << result << '\n';

    return 0;
}
